var a=`1189-churros`;var i=`world-1189`;var t=`MX`;var o=`central-america-caribbean`;var n=8;var s=49;var u={en:`Churros`,ua:`Чурос`};var h={en:`Churros is a dish from Mexico prepared with all-purpose flour, chicken egg. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Чурос, страва кухні країни Мексика, яку готують із таких продуктів: пшеничне борошно універсальне, куряче яйце. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Bring the measured water, butter and sugar to a simmer in a saucepan to prepare the hot base for churro dough; do not drain it.`,ua:`Доведіть зазначені воду, масло та цукор до кипіння в сотейнику, готуючи гарячу основу для тіста чурос; не зливайте рідину.`,t:[`boiling`],m:8,i:[[`water`,330,`ml`],[`unsalted-butter`,70,`g`],[`white-granulated-sugar`,30,`g`]]},{en:`Remove the hot butter-water mixture from heat and beat in flour to form a smooth panade; cool briefly before beating in the eggs.`,ua:`Зніміть гарячу масляно-водну суміш із вогню та вмішайте борошно на гладку заварну основу; трохи остудіть перед додаванням яєць.`,t:[`mixing`],m:12,i:[[`all-purpose-flour`,320,`g`],[`chicken-egg`,3,`pcs`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 16 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 16 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:16,i:[[`canola-oil`,850,`ml`]]},{en:`Immediately toss the fried churros in cinnamon sugar while warm; this is a sweet coating, not ordinary savory breading.`,ua:`Відразу обкачайте ще теплі чурос у цукрі з корицею; це солодке покриття, а не солона паніровка.`,t:[`standard-breading`],m:3,i:[[`white-granulated-sugar`,110,`g`],[`ground-cinnamon`,8,`g`]]}];var g={slug:a,id:i,country:`MX`,region:o,servings:8,minutes:49,title:u,text:h,steps:d};export{t as country,g as default,i as id,s as minutes,o as region,n as servings,a as slug,d as steps,h as text,u as title};